// August 2021
// Created for Crayon Codes

let squares;
let freeCorners;

const iterationsPerFrame = 7;
const shadowColor = "#00000088";

//palette colours are ordered as follows:
//background A, background B, stroke, main, extra 
const palettes = [
	["#ff7e6b", "#f33e6b", "#8c5e58", "#a9f0d1", "#fff7f8"],
	["#70c1b3", "#aaf0d3", "#50514f", "#ffe066", "#247ba0"],
	["#f8f9fb", "#f9f6e0", "#45454c", "#ef9643", "#f06543"],
	["#3c1642", "#386375", "#086375", "#b2ff9e", "#1dd3b0"],
	["#deFbE4", "#f7f9fb", "#02906c", "#eafc70", "#02b08c"],
	["#6cbbd4", "#5863b1", "#5282a1", "#fee8f7", "#c1f29b"],
	["#211E20", "#413550", "#14777F", "#F6CCA5", "#5EB8A5"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222", "#ff0000"],
	["#ffffff", "#e2e2ec", "#1e32aa", "#0564ff", "#82afff"] //new Processing colors
]

let prevCellSize = 20
let prevNoiseScale = 0.01
let prevMaxSquareSize = 80;
let prevP = 1.6
let prevXMargin = 130
let prevYMargin = 130
let prevMinSpacing = 0
let prevSeed = Math.floor(Math.random() * 10000)

let colorStopDistance
let backgroundGradient;

/** OPC START **/
OPC.slider("seed", prevSeed, 0, 10e5, 1);
OPC.slider("paletteIndex", 0, 0, palettes.length - 1, 1);
OPC.slider("displayMode", 1, 1, 4, 1);
OPC.slider("strokeThickness", 4, 2, 8, 0.25);
OPC.slider("cellSize", prevCellSize, 4, 32, 1);
OPC.slider("squarePadding", 12, 0, 20, 2);
OPC.slider("minSpacing", prevMinSpacing, 0, 5, 1);
OPC.slider("maxSquareSize", prevMaxSquareSize, 10, 150)
OPC.slider("noiseScale", prevNoiseScale, 0.001, 0.1, 0.001);
OPC.slider("p", prevP, 0.5, 4.5, 0.01);
OPC.slider("shadowBlur", 0, 0, 30, 5);
OPC.slider("xMargin", prevXMargin, 0, window.innerWidth / 2 - 100);
OPC.slider("yMargin", prevYMargin, 0, window.innerHeight / 2 - 100);
/** OPC END **/

function setup() {

	createCanvas(windowWidth, windowHeight);

	rectMode(CENTER);
	noStroke();
	drawingContext.shadowColor = shadowColor;

	resetGeneration();
}

function draw() {

	//because there isn't an onChange event yet for the slider library, 
	//we have to check if each variable (that affects generation) has changed each frame
	if (prevCellSize !== cellSize ||
		prevNoiseScale !== noiseScale ||
		prevMaxSquareSize !== maxSquareSize ||
		prevP !== p || prevXMargin != xMargin ||
		prevYMargin != yMargin ||
		prevMinSpacing !== minSpacing ||
		prevSeed != seed
	) {
		prevCellSize = cellSize
		prevNoiseScale = noiseScale
		prevMaxSquareSize = maxSquareSize
		prevP = p
		prevXMargin = xMargin
		prevYMargin = yMargin
		prevMinSpacing = minSpacing
		prevSeed = seed

		resetGeneration();
	}

	for (let i = 0; i < iterationsPerFrame; i++) {
		generateStep()
	}

	palette = palettes[paletteIndex]

	// add a very slight gradient to the background
	const colorStopDistance = max(width, height) * 1.15;
	backgroundGradient = drawingContext.createLinearGradient(
		width / 2 - colorStopDistance / 2 * cos(gradientAngle),
		height / 2 - colorStopDistance / 2 * sin(gradientAngle),
		width / 2 + colorStopDistance / 2 * cos(gradientAngle),
		height / 2 + colorStopDistance / 2 * sin(gradientAngle)
	);
	backgroundGradient.addColorStop(0, palette[0]);
	backgroundGradient.addColorStop(1, palette[1]);

	drawStuff();

}

function drawStuff() {

	drawingContext.fillStyle = backgroundGradient;
	rect(width/2, height/2, width, height);

	const sp = min(squarePadding, cellSize);

	for (let i = 0; i < (displayMode == 2 ? maxSquareSize / (strokeThickness * 9) : 1); i++) {

		drawingContext.fillStyle = (palette[2]);

		if (shadowBlur > 0) {
			drawingContext.shadowBlur = shadowBlur;
			drawSquares(sp - strokeThickness * i * 9);
			drawingContext.shadowBlur = 0;
		}

		drawSquares(sp - strokeThickness * i * 9);

		if (displayMode === 1 || displayMode === 2 || displayMode === 3) {

			drawingContext.fillStyle = (displayMode === 3 ? palette[4] : palette[3]);
			drawSquares(sp - strokeThickness * (i * 9 + 2));

			drawingContext.fillStyle = (palette[2]);
			drawSquares(sp - strokeThickness * (i * 9 + 4));

			drawingContext.fillStyle = (displayMode === 3 ? palette[3] : backgroundGradient);
			drawSquares(sp - strokeThickness * (i * 9 + 6));


		} else if (displayMode === 4) {
			drawingContext.fillStyle = (palette[3]);
			drawSquares(sp - strokeThickness * 2);

		}
	}

}

function drawSquares(extra) {
	for (let {
			x,
			y,
			size
		} of squares) {
		if (size + extra > min(2, cellSize)) {
			square(x, y, size + extra);

			//// wow, you found the secret wonky square mode:
			//// i considered implementing this but didn't due to technical and time constraints
			// beginShape()
			// for (let angle = TAU / 8; angle < TAU; angle += TAU / 4) {
			// 	let cornerX = x + (size + extra) * cos(angle)/sqrt(2) +random(-1.3, 1.3)
			// 	let cornerY = y + (size + extra) * sin(angle)/sqrt(2)+random(-1.3, 1.3)
			// 	vertex(cornerX, cornerY)
			// }
			// endShape()
		}

	}
}


function keyPressed() {
	if (key === "s") save();
}

function generate() {
	resetGeneration();
	while (freeCorners.length > 0) {
		generateStep();
	}
}

function resetGeneration() {
	noiseSeed(seed);
	randomSeed(seed);

	gradientAngle = random(TAU);

	squares = []
	freeCorners = []
	let x = width / 2;
	x -= x % cellSize
	let y = height / 2;
	y -= y % cellSize

	let size = getCellSizeAt(x, y);

	squares.push({
		x,
		y,
		size,
		id: 0
	})

	for (let xDirection = -1; xDirection <= 1; xDirection += 2) {
		for (let yDirection = -1; yDirection <= 1; yDirection += 2) {
			freeCorners.push({
				x: x + size / 2 * xDirection,
				y: y + size / 2 * yDirection,
				size,
				xDirection,
				yDirection,
				squareId: 0
			});
		}
	}
}

function generateStep() {

	let isValidCorner = false

	//loop until we find a corner we can place a new square on, 
	//or until we have run out of available corners
	while (!isValidCorner && freeCorners.length > 0) {

		//pick a random corner and remove it from the list of available corners
		let chosenCorner = freeCorners.splice(floor(random(freeCorners.length)), 1)[0];

		//we need to find the distance between the corner we have chosen and the closest square
		let minDistance = Infinity;
		for (let square of squares) {

			//ignore the square that we are branching off
			if (square.id !== chosenCorner.squareId) {

				let xDistance = (square.x - chosenCorner.x) * chosenCorner.xDirection - square.size / 2
				let yDistance = (square.y - chosenCorner.y) * chosenCorner.yDirection - square.size / 2

				//if the conditions below are met, then no matter how big the next square we place is, 
				//it won't intersect with this one so we can ignore it
				if (xDistance < -square.size) xDistance = Infinity;
				if (yDistance < -square.size) yDistance = Infinity;


				//if it's the same distance in the x and y direction, it could just be touching at the corner, so we'll allow it
				//---
				//this is sort of a cheat way of testing for corner connections, since it only allows connections on the opposite corner
				//however, it leads to more interesting patterns than allowing the algorithm to fill in every space that only touches by a corner
				if (xDistance == yDistance) {
					xDistance += cellSize;
					yDistance += cellSize
				}

				if (xDistance < minDistance && yDistance < minDistance) minDistance = max(xDistance, yDistance);
			}
		}

		if (minDistance > cellSize + minSpacing * cellSize &&
			constrain(chosenCorner.x, xMargin, width - xMargin) === chosenCorner.x &&
			constrain(chosenCorner.y, yMargin, height - yMargin) === chosenCorner.y
		) {
			//we can place a new square at this corner
			isValidCorner = true;

			let size = getCellSizeAt(chosenCorner.x, chosenCorner.y);
			if (size >= minDistance) size = minDistance - cellSize - minDistance % cellSize;

			const x = chosenCorner.x + chosenCorner.xDirection * size / 2;
			const y = chosenCorner.y + chosenCorner.yDirection * size / 2;
			squares.push({
				x,
				y,
				size,
				id: squares.length
			})
			// drawSquare(x, y, size)
			for (let xDirection = -1; xDirection <= 1; xDirection += 2) {
				for (let yDirection = -1; yDirection <= 1; yDirection += 2) {
					if (xDirection !== -chosenCorner.xDirection || yDirection !== -chosenCorner.yDirection) {
						freeCorners.push({
							x: x + size / 2 * xDirection,
							y: y + size / 2 * yDirection,
							size,
							xDirection,
							yDirection,
							squareId: squares.length - 1
						});
					}
				}
			}
		}
	}
}

function getCellSizeAt(x, y) {
	let size = map(noise(x * noiseScale, y * noiseScale) ** p, 0.18 ** p, 0.82 ** p, cellSize, maxSquareSize);
	size = constrain(size, cellSize, maxSquareSize);
	size -= size % cellSize;
	return size;
}

function keyPressed() {
	if (key.toLowerCase() === "s") {
		save();
	}
}

